package com.realstant.nativegame; public final class WeatherSystem { private WeatherType type=WeatherType.CLEAR; private float intensity; public void set(WeatherType t){type=t;intensity=t==WeatherType.CLEAR?0:1;} public WeatherType get(){return type;} public float intensity(){return intensity;} public void update(float dt){intensity+=(type==WeatherType.CLEAR?0-intensity:1-intensity)*Math.min(1,dt);} }
